        localDate: p[0], openPrice: Number(p[1]), highPrice: Number(p[2]),
        lowPrice: Number(p[3]), closePrice: Number(p[4]), accumulatedTradingVolume: Number(p[5] || 0)
      };
    }).filter(r => r.closePrice > 0 && /^\d{8}$/.test(r.localDate));
