  // 전일 거래일 날짜 계산 (주말/공휴일 제외) — 장중 당일을 endDate로 쓰면 Naver API가 빈 배열 반환
  const getNaverPrevDay = () => {
    let d = new Date(Date.now() + 9 * 3600000 - 24 * 3600000);
