  const isGarbled = (s) => !s || !/^[가-힣ᄀ-ᇿ㄰-㆏㈀-㈟！-ﾟ一-鿿 -~]+$/.test(s);
  const allCodes = [...new Set(details.map((d) => d.code))];
  for (const code of allCodes) {
    const cached = store.naverNames && store.naverNames[code];
